  ins.sort((a, b) => b.line - a.line || b.i - a.i)
  for (const o of ins) {
    const target = lines[o.line - 1]
    if (target === undefined) throw new Error(`${file}:${o.line} out of range`)
    lines.splice(o.line - 1, 0, indent(target) + o.text)
    n++
  }
  fs.writeFileSync(p, lines.join('\n'))
}
